// PBE Signal 10 API (issue #52). Two record populations, never merged:
//   origin=HISTORICAL_REPLAY  bundled, reproducible backtest artifacts (data/signal10/*, generated by scripts/signal10)
//   origin=FORWARD_PAPER      the live paper account ledger on tkmln (pred_s10_*), written by the signal10 cron lane
// Every member route is behind requireAllAccess + privateJson. /v1/signal10/proof is the public evidence layer: versions,
// dates, hashes, counts and the hypothetical backtest headline with its disclosure. No rankings or holdings in public.
import SUMMARY from '../../../data/signal10/backtest-summary.json' with { type: 'json' };
import NAV from '../../../data/signal10/backtest-nav.json' with { type: 'json' };
import LEDGER from '../../../data/signal10/backtest-ledger.json' with { type: 'json' };
import RANKS from '../../../data/signal10/backtest-ranks.json' with { type: 'json' };
import VARIANTS from '../../../data/signal10/research-variants.json' with { type: 'json' };
import { ACCOUNT, fetchChart, quoteFromChart, navFromQuotes, nyClock, isWeekday, restoreState, runOpen, runEod, runMark, due } from '../../../src/signal10/forward.js';
import { MODEL_VERSION, POLICY_VERSION, MANAGER, RANK, DISCLOSURE } from '../../../src/signal10/policy.js';

const QUOTE_TTL_S = 15;
const pick = (o, keys) => Object.fromEntries(keys.filter((k) => k in o).map((k) => [k, o[k]]));

export function sessionState(nowIso) {
  const c = nyClock(nowIso);
  if (!isWeekday(c)) return { state: 'CLOSED_WEEKEND', label: 'MARKET CLOSED · WEEKEND', ny: c };
  if (c.minutes < 9 * 60 + 30) return { state: 'PRE_MARKET', label: 'PRE-MARKET · LAST CLOSE SHOWN', ny: c };
  if (c.minutes < 16 * 60) return { state: 'OPEN', label: 'U.S. REGULAR SESSION OPEN', ny: c };
  return { state: 'CLOSED', label: 'MARKET CLOSED · LAST CLOSE', ny: c };
}

// Quotes: one source call per symbol, edge-cached 15 s (caches.default; a fresh Response is built for every request).
async function quotes(symbols, ctx) {
  const cache = caches.default;
  return Promise.all(symbols.map(async (s) => {
    const key = new Request(`https://signal10.quote.cache/${encodeURIComponent(s)}`);
    const hit = await cache.match(key);
    if (hit) return hit.json();
    const q = quoteFromChart(await fetchChart(s, { range: '1d', interval: '1d' }));
    if (q) ctx.waitUntil(cache.put(key, new Response(JSON.stringify(q), { headers: { 'cache-control': `max-age=${QUOTE_TTL_S}`, 'content-type': 'application/json' } })));
    return q;
  }));
}

async function forwardHead(store) {
  const [state] = await store.select('pred_s10_events', { account: `eq.${ACCOUNT}`, type: 'eq.STATE', select: 'seq,d,payload,hash,inserted_at' }, { limit: 1, order: 'seq.desc' });
  const [last] = await store.select('pred_s10_events', { account: `eq.${ACCOUNT}`, select: 'seq,hash,inserted_at' }, { limit: 1, order: 'seq.desc' });
  return { state: state || null, lastSeq: last?.seq || 0, lastHash: last?.hash || null, lastAt: last?.inserted_at || null };
}

export function backtestHeadline() {
  const s = SUMMARY;
  const m = (x) => pick(x, ['start', 'end', 'startCents', 'endCents', 'gainCents', 'totalReturn', 'cagr', 'maxDrawdown', 'years']);
  return { origin: 'HISTORICAL_REPLAY', label: s.label, disclosure: s.disclosure, model: s.model, policy: s.policy, data_cutoff: s.data_cutoff,
    strategy: m(s.strategy), SPY: m(s.benchmarks.SPY), QQQ: m(s.benchmarks.QQQ), dataset_sha256: s.dataset_sha256, ledger_sha256: s.ledger_sha256, nav_sha256: s.nav_sha256 };
}

export async function handleSignal10({ req, env, ctx, p, url, store, requireAllAccess, privateJson, json, tokenMatches }) {
  if (!p.startsWith('/v1/signal10') && !p.startsWith('/admin/signal10')) return null;

  // admin: manual lane trigger (dry runs are not supported: a run either claims and writes, or skips)
  if (p === '/admin/signal10/run' && req.method === 'POST') {
    if (!(await tokenMatches(req, env.ADMIN_TOKEN))) return json({ error: 'unauthorized' }, 401, 'no-store');
    const now = url.searchParams.get('now') || new Date().toISOString();
    const kind = url.searchParams.get('kind');
    const args = { store, now, workerVersion: env.CF_VERSION_METADATA?.id ?? null, startDate: env.SIGNAL10_START };
    const r = kind === 'OPEN' ? await runOpen(args) : kind === 'EOD' ? await runEod(args) : kind === 'MARK' ? await runMark(args) : { error: 'kind must be OPEN|EOD|MARK' };
    return json(r, 200, 'no-store');
  }

  if (p === '/v1/signal10/proof') {
    let fwd = { status: 'NOT_STARTED' };
    try {
      const h = await forwardHead(store);
      const [snap] = await store.select('pred_s10_snapshots', { select: 'd,model_version,content_sha256,frozen_at,eligible' }, { limit: 1, order: 'd.desc' });
      const [fund] = await store.select('pred_s10_events', { account: `eq.${ACCOUNT}`, type: 'eq.FUNDING', select: 'd,inserted_at,hash' }, { limit: 1, order: 'seq.asc' });
      if (fund) fwd = { status: 'RUNNING', origin: 'FORWARD_PAPER', inception: fund.d, funded_at: fund.inserted_at, funding_hash: fund.hash, ledger_events: h.lastSeq, ledger_head_hash: h.lastHash, ledger_head_at: h.lastAt,
        latest_snapshot: snap ? { d: snap.d, model: snap.model_version, content_sha256: snap.content_sha256, frozen_at: snap.frozen_at, eligible: snap.eligible } : null };
    } catch (e) { fwd = { status: 'UNAVAILABLE' }; }
    return json({ product: 'PBE Signal 10', model: MODEL_VERSION, policy: POLICY_VERSION, disclosure: DISCLOSURE, forward: fwd, backtest: backtestHeadline(), generated_at: new Date().toISOString() }, 200, 'public, max-age=60');
  }

  // ---------------- member routes ----------------
  const g = await requireAllAccess(req, env); if (!g.ok) return g.res;
  const access = { tier: g.m.membership.state };

  if (p === '/v1/signal10/backtest') {
    const { contributions, final_holdings, ...rest } = SUMMARY;
    return privateJson({ ...rest, contributions: { top: contributions.slice(0, 15), bottom: contributions.slice(-15).reverse(), count: contributions.length }, final_holdings, nav: NAV, research_variants: VARIANTS, access });
  }
  if (p === '/v1/signal10/backtest/ranks') return privateJson({ ...RANKS, access });
  if (p === '/v1/signal10/ledger') {
    const origin = url.searchParams.get('origin') || 'HISTORICAL_REPLAY';
    if (origin === 'HISTORICAL_REPLAY') return privateJson({ origin, ledger_sha256: LEDGER.ledger_sha256, events: LEDGER.events.filter((e) => e.type !== 'ORDER'), access });
    if (origin !== 'FORWARD_PAPER') return privateJson({ error: 'origin must be HISTORICAL_REPLAY or FORWARD_PAPER' }, 400);
    // Every row, STATE included, so a reader can recompute the whole hash chain. Bounded: ?since=<seq> (exclusive),
    // ?d=YYYY-MM-DD for one session, ?limit (default 2000, max 5000).
    const q = { account: `eq.${ACCOUNT}`, select: 'seq,type,d,payload,hash,prev_hash,model_version,policy_version,inserted_at' };
    const since = Number.parseInt(url.searchParams.get('since') || '', 10);
    if (Number.isFinite(since) && since > 0) q.seq = `gt.${since}`;
    const day = url.searchParams.get('d');
    if (day && /^\d{4}-\d{2}-\d{2}$/.test(day)) q.d = `eq.${day}`;
    const limit = Math.min(5000, Math.max(1, Number.parseInt(url.searchParams.get('limit') || '2000', 10) || 2000));
    const rows = await store.select('pred_s10_events', q, { order: 'seq.asc', limit });
    return privateJson({ origin, account: ACCOUNT, verify: 'hash = sha256(prev_hash + canonical({account,origin,seq,type,d,payload,model_version,policy_version})), canonical = JSON with sorted keys', events: rows.map((r) => ({ ...r, account: ACCOUNT, origin })), access });
  }
  if (p === '/v1/signal10/today') {
    const snaps = await store.select('pred_s10_snapshots', { select: 'd,model_version,frozen_at,eligible,excluded,ranks,held_ranks,regime,members,content_sha256,data_cutoff' }, { limit: 2, order: 'd.desc' });
    const h = await forwardHead(store);
    const st = h.state ? restoreState(h.state.payload).st : null;
    if (!snaps.length) {
      const last = RANKS.rows.at(-1); const prev = RANKS.rows.at(-2);
      return privateJson({ origin: 'HISTORICAL_REPLAY', label: `Replay snapshot · ${last[0]} close (the forward lane has not frozen its first snapshot yet)`, model: MODEL_VERSION, d: last[0], eligible: last[1],
        top: last[2].map(([symbol, score], i) => ({ rank: i + 1, symbol, score, prevRank: (prev[2].findIndex((x) => x[0] === symbol) + 1) || null })), access });
    }
    const [cur, prev] = snaps;
    const prevRank = new Map((prev?.ranks || []).map((r) => [r.symbol, r.rank]));
    const curTop = new Set(cur.ranks.slice(0, 10).map((r) => r.symbol));
    const exited = (prev?.ranks || []).slice(0, 10).filter((r) => !curTop.has(r.symbol)).map((r) => ({ symbol: r.symbol, name: r.name, prevRank: r.rank, rank: cur.ranks.find((x) => x.symbol === r.symbol)?.rank ?? null }));
    const held = new Set(st ? Object.keys(st.positions) : []);
    const pending = st ? st.pending.map((o) => pick(o, ['side', 'symbol', 'qty', 'targetCents', 'reason', 'rank', 'score'])) : [];
    const top = cur.ranks.slice(0, 30).map((r) => ({ ...r, prevRank: prevRank.get(r.symbol) ?? null, held: held.has(r.symbol), streak: st?.streak?.[r.symbol] || 0,
      status: r.rank > 10 && (!prevRank.has(r.symbol) || prevRank.get(r.symbol) > 10) ? null : !prev || !prevRank.has(r.symbol) || prevRank.get(r.symbol) > 10 ? 'NEW' : r.rank < prevRank.get(r.symbol) ? 'RISING' : r.rank > prevRank.get(r.symbol) ? 'FALLING' : 'HOLDING' }));
    return privateJson({ origin: 'FORWARD_PAPER', model: cur.model_version, d: cur.d, frozen_at: cur.frozen_at, data_cutoff: cur.data_cutoff, eligible: cur.eligible, excluded: cur.excluded, regime: cur.regime,
      members: cur.members, content_sha256: cur.content_sha256, prev_d: prev?.d || null, top, exited, pending, access });
  }
  if (p === '/v1/signal10/live') {
    const now = new Date().toISOString();
    const session = sessionState(now);
    const h = await forwardHead(store);
    // backtest continuity showcase: the replay's final holdings marked with the same live quotes (never mixed with forward)
    const bt = SUMMARY.final_holdings;
    let fwd = null;
    let syms = ['SPY', 'QQQ', ...bt.map((x) => x.symbol)];
    let st = null, bench = null;
    if (h.state) { ({ st, bench } = restoreState(h.state.payload)); syms = [...new Set([...Object.keys(st.positions), ...syms])]; }
    const q = (await quotes([...new Set(syms)], ctx)).filter(Boolean);
    const qBy = Object.fromEntries(q.map((x) => [x.symbol, x]));
    if (session.state === 'OPEN' && session.ny.minutes >= 9 * 60 + 45 && qBy.SPY && nyClock(qBy.SPY.quoteTime).date !== session.ny.date) Object.assign(session, { state: 'CLOSED_HOLIDAY', label: 'MARKET CLOSED · NO SESSION TODAY · LAST CLOSE' });
    if (st) {
      const nav = navFromQuotes(st, q, now);
      const eod = await store.select('pred_s10_marks', { account: `eq.${ACCOUNT}`, kind: 'eq.EOD_CLOSE', select: 'd,observed_at,nav_cents,cash_cents,benchmarks' }, { order: 'd.asc' });
      const intraday = await store.select('pred_s10_marks', { account: `eq.${ACCOUNT}`, kind: 'eq.INTRADAY', d: `eq.${session.ny.date}`, select: 'observed_at,nav_cents,coverage,benchmarks' }, { order: 'observed_at.asc' });
      const lastEod = eod.at(-1) || null;
      const priorClose = eod.filter((x) => x.d < session.ny.date).at(-1) || null;
      const positions = Object.entries(st.positions).map(([sym, pos]) => {
        const lq = qBy[sym]; const pn = nav.positions.find((x) => x.symbol === sym);
        return { symbol: sym, ticker: pos.ticker, name: pos.name || lq?.name || null, qty: pos.qty, costCents: pos.costCents, avgCost: pos.costCents / 100 / pos.qty, entryDate: pos.entryDate,
          price: lq?.price ?? null, quoteTime: lq?.quoteTime ?? null, previousClose: lq?.previousClose ?? null, fresh: pn?.fresh ?? false, valueCents: pn?.valueCents ?? null, dividendsCents: pos.dividendsCents || 0 };
      });
      const benchLive = Object.fromEntries(Object.entries(bench).map(([k, b]) => { const n = navFromQuotes(b, q, now); return [k, { navCents: n.complete ? n.navCents : null, cashCents: b.cashCents, positions: Object.entries(b.positions).map(([s, x]) => ({ symbol: s, qty: x.qty, costCents: x.costCents })) }]; }));
      fwd = {
        origin: 'FORWARD_PAPER', account: ACCOUNT, label: 'PBE PAPER ACCOUNT · STARTING $10,000 · SIMULATED', inception: st.inception, startingCents: MANAGER.startingCashCents,
        fillSessions: st.fillSessions, windowSessions: MANAGER.initialWindowSessions, cashCents: st.cashCents, realizedCents: st.realizedCents, dividendsCents: st.dividendsCents, slippageCents: st.slippageCents,
        nav: { cents: nav.navCents, complete: nav.complete, coverage: nav.coverage }, lastEod, priorClose, positions,
        pending: st.pending.map((o) => pick(o, ['side', 'symbol', 'qty', 'targetCents', 'reason', 'rank', 'score', 'd'])),
        streak: st.streak, benchmarks: benchLive, eodHistory: eod, intraday, ledgerSeq: h.lastSeq, ledgerHeadHash: h.lastHash, stateAsOf: h.state.d
      };
    }
    const continuation = { origin: 'HISTORICAL_REPLAY', label: 'Backtested Holdings · hypothetical continuation', asOf: SUMMARY.data_cutoff,
      cashCents: SUMMARY.strategy.cashCents, holdings: bt.map((x) => ({ ...pick(x, ['symbol', 'name', 'qty', 'close', 'closeDate', 'costCents', 'valueCents', 'entryDate']), price: qBy[x.symbol]?.price ?? null, quoteTime: qBy[x.symbol]?.quoteTime ?? null })) };
    return privateJson({ now, session, quoteSource: 'Yahoo Finance public chart endpoint (source trade timestamps shown; may be delayed; not exchange-licensed)', quoteCacheSeconds: QUOTE_TTL_S,
      forward: fwd, continuation, benchmarksQuotes: { SPY: qBy.SPY || null, QQQ: qBy.QQQ || null }, disclosure: DISCLOSURE, access });
  }
  return privateJson({ error: 'not_found' }, 404);
}

// Scheduled entry (FAST one-minute cron). Each job is time-gated and idempotent; errors never touch other lanes.
export async function signal10Tick(env, minuteAt) {
  const store = env.__store;
  const d = due(minuteAt);
  const out = {};
  const args = { store, now: minuteAt, workerVersion: env.CF_VERSION_METADATA?.id ?? null, startDate: env.SIGNAL10_START };
  if (d.open) out.open = await runOpen(args).catch((e) => ({ error: e.message }));
  if (d.mark) out.mark = await runMark(args).catch((e) => ({ error: e.message }));
  if (d.eod && d.minutes % 2 === 0) out.eod = await runEod(args).catch((e) => ({ error: e.message }));
  return out;
}
